enum Route: Hashable { case amount, corporateAmount, confirm, done }

@State private var path: [Route] = []

var body: some View {
    NavigationStack(path: $path) {
        SelectView { account in
            path.append(account.isCorporate ? .corporateAmount : .amount)
        }
        .navigationDestination(for: Route.self) { route in view(for: route) }
    }
}
